import React, { useState } from 'react';
import AuthModal from '../../components/modals/AuthModal';
import WalletButton from '../../components/ui/WalletButton';
import CanvasPage from '../canvas/page';
import { useSessionStore } from '../../store/session.store';

export default function LendingPage() {
  const [showAuth, setShowAuth] = useState(false);
  const isAuthenticated = useSessionStore((s) => s.isAuthenticated);

  return (
    <div className="min-h-screen bg-[#080A0F] text-white">
      <div className="fixed inset-x-0 top-0 z-50 border-b border-white/10 bg-[#080A0F]/95 backdrop-blur-md px-6 py-4">
        <div className="mx-auto flex max-w-7xl items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <img src="/movipa-logo.svg" alt="MOVIPA" className="w-7 h-7" />
            <div>
              <div className="text-sm font-semibold">Manage</div>
              <div className="text-xs text-white/50">Lending workspace</div>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <WalletButton />
            {!isAuthenticated && (
              <button
                onClick={() => setShowAuth(true)}
                className="rounded-full border border-white/15 bg-white/5 px-4 py-2 text-sm font-semibold text-white hover:bg-white/10 transition"
              >
                Sign In
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="pt-[88px]">
        <div className="max-w-full mx-auto">
          <CanvasPage />
        </div>
      </div>

      {!isAuthenticated && showAuth && <AuthModal />}
    </div>
  );
}
