import React, { useState } from 'react';
import { useAccount, useConnect } from 'wagmi';
import { useSessionStore } from '../../store/session.store';

const API_BASE = process.env.REACT_APP_API_BASE_URL || 'http://127.0.0.1:8001';
const walletOptions = ['MetaMask', 'Rabby', 'Phantom', 'WalletConnect'];

export default function AuthModal() {
  const { connect, connectors } = useConnect();
  const { address, isConnected } = useAccount();
  const injected = connectors.find((connector) => /meta|injected|browser/i.test(connector.name));
  const { loginWithWallet, loginWithGoogle } = useSessionStore();
  const [email, setEmail] = useState('');
  const [error, setError] = useState('');

  const notifyBackend = async (walletAddress: string, authMethod: 'wallet' | 'google', email?: string) => {
    try {
      await fetch(`${API_BASE}/api/v2/auth/signin`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          wallet_address: walletAddress,
          auth_method: authMethod,
          email,
          embedded_wallet: authMethod === 'google' ? walletAddress : undefined,
        }),
      });
    } catch {
      // Fail silently; backend analytics should not block auth flow.
    }
  };

  const connectWallet = async () => {
    if (!injected) {
      setError('Tarayıcı cüzdanı bulunamadı.');
      return;
    }

    try {
      await connect({ connector: injected });
      if (isConnected && address) {
        await notifyBackend(address, 'wallet');
      }
      loginWithWallet();
    } catch (err: any) {
      setError(err?.message || 'Cüzdan bağlantısı başarısız oldu.');
    }
  };

  const continueWithGoogle = async () => {
    if (!email.trim() || !email.includes('@')) {
      setError('Enter a valid Google email.');
      return;
    }
    const normalizedEmail = email.trim().toLowerCase();
    const derivedWallet = Array.from(normalizedEmail)
      .reduce((acc, c) => acc + c.charCodeAt(0), 0)
      .toString(16)
      .padStart(40, '0')
      .slice(0, 40);
    const walletAddress = `0x${derivedWallet}`;
    await notifyBackend(walletAddress, 'google', normalizedEmail);
    loginWithGoogle(normalizedEmail);
  };

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
      <div className="w-full max-w-2xl rounded-3xl border border-white/10 bg-[#11151F] p-6 md:p-8">
        <h2 className="text-2xl text-white font-semibold tracking-tight">Sign in to MOVIPA</h2>
        <p className="text-white/50 text-sm mt-1">Secure wallet and Google access in one place.</p>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-6">
          <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4">
            <p className="text-xs uppercase tracking-wider text-white/40 mb-3">Option A</p>
            <h3 className="text-white font-medium mb-2">Continue with Wallet</h3>
            <div className="space-y-2 mb-3">
              {walletOptions.map((w) => (
                <div key={w} className="px-3 py-2 rounded-xl border border-white/10 text-sm text-white/80 bg-[#0E121A]">
                  {w}
                </div>
              ))}
            </div>
            <button onClick={connectWallet} className="w-full py-2.5 rounded-xl bg-white text-black text-sm font-medium hover:bg-white/90">
              Connect Wallet
            </button>
          </div>

          <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4">
            <p className="text-xs uppercase tracking-wider text-white/40 mb-3">Option B</p>
            <h3 className="text-white font-medium mb-1">Continue with Google</h3>
            <p className="text-white/45 text-xs mb-3">Magic link + embedded MPC wallet</p>
            <input
              value={email}
              onChange={(e) => { setEmail(e.target.value); setError(''); }}
              placeholder="you@gmail.com"
              className="w-full rounded-xl border border-white/10 bg-[#0E121A] px-3 py-2 text-sm text-white placeholder:text-white/30 outline-none"
            />
            <button onClick={continueWithGoogle} className="w-full mt-3 py-2.5 rounded-xl bg-white text-black text-sm font-medium hover:bg-white/90">
              Continue with Google
            </button>
            <p className="text-white/35 text-xs mt-2">Wallet management is handled for you.</p>
          </div>
        </div>

        {error && <p className="text-red-300 text-xs mt-3">{error}</p>}
      </div>
    </div>
  );
}
