import React, { useMemo, useState } from 'react';
import { useUiStore } from '../../store/ui.store';
import { useSessionStore } from '../../store/session.store';

const GOALS = [
  'Arbitrage',
  'Earn Yield',
  'Leverage',
  'Bridge Assets',
  'Automate Strategies',
  'Explore Templates',
] as const;

export default function OnboardingFlow() {
  const { setView } = useUiStore();
  const {
    setIntentGoals,
    setExperienceMode,
    setSecurityPrefs,
    securityPrefs,
    completeOnboarding,
  } = useSessionStore();

  const [step, setStep] = useState(0);
  const [selectedGoals, setSelectedGoals] = useState<string[]>([]);
  const [mode, setMode] = useState<'simple' | 'advanced'>('simple');

  const title = useMemo(() => {
    if (step === 0) return 'Welcome to MOVIPA';
    if (step === 1) return 'What do you want to do?';
    if (step === 2) return 'Choose your experience';
    if (step === 3) return 'Security Preferences';
    return "You're ready.";
  }, [step]);

  const toggleGoal = (goal: string) => {
    setSelectedGoals((prev) =>
      prev.includes(goal) ? prev.filter((g) => g !== goal) : [...prev, goal]
    );
  };

  const finish = () => {
    setIntentGoals(selectedGoals);
    setExperienceMode(mode);
    completeOnboarding();
    setView('canvas');
  };

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-[210] flex items-center justify-center p-4">
      <div className="w-full max-w-2xl rounded-3xl border border-white/10 bg-[#11151F] p-6 md:p-8">
        <p className="text-xs text-white/40 uppercase tracking-wider">Step {step + 1} / 5</p>
        <h2 className="text-2xl text-white font-semibold tracking-tight mt-2">{title}</h2>

        {step === 0 && (
          <p className="text-white/55 text-sm mt-3">
            MOVIPA executes complex DeFi strategies through encrypted intent routing.
          </p>
        )}

        {step === 1 && (
          <div className="flex flex-wrap gap-2 mt-4">
            {GOALS.map((goal) => (
              <button
                key={goal}
                onClick={() => toggleGoal(goal)}
                className={`px-3 py-1.5 rounded-full text-sm border ${selectedGoals.includes(goal)
                  ? 'bg-white text-black border-white'
                  : 'bg-white/5 text-white/80 border-white/15'}`}
              >
                {goal}
              </button>
            ))}
          </div>
        )}

        {step === 2 && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mt-4">
            <button
              onClick={() => setMode('simple')}
              className={`text-left rounded-2xl border p-4 ${mode === 'simple' ? 'border-white bg-white text-black' : 'border-white/15 bg-white/[0.03] text-white'}`}
            >
              <h3 className="font-medium">Simple</h3>
              <p className={mode === 'simple' ? 'text-black/70 text-sm mt-1' : 'text-white/55 text-sm mt-1'}>
                Less settings, less technical detail, more automation.
              </p>
            </button>
            <button
              onClick={() => setMode('advanced')}
              className={`text-left rounded-2xl border p-4 ${mode === 'advanced' ? 'border-white bg-white text-black' : 'border-white/15 bg-white/[0.03] text-white'}`}
            >
              <h3 className="font-medium">Advanced</h3>
              <p className={mode === 'advanced' ? 'text-black/70 text-sm mt-1' : 'text-white/55 text-sm mt-1'}>
                Full canvas control, execution and routing configs.
              </p>
            </button>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-3 mt-4">
            {[
              { key: 'privateExecution', label: 'Private Execution' },
              { key: 'mevProtection', label: 'MEV Protection' },
              { key: 'autoRevert', label: 'Auto-Revert Unsafe Trades' },
              { key: 'simulationBeforeExecution', label: 'Simulation Before Execution' },
            ].map((item) => (
              <div key={item.key} className="rounded-xl border border-white/10 bg-white/[0.03] p-3 flex items-center justify-between">
                <span className="text-sm text-white">{item.label}</span>
                <button
                  onClick={() => setSecurityPrefs({ [item.key]: !securityPrefs[item.key as keyof typeof securityPrefs] } as any)}
                  className={`w-11 h-6 rounded-full transition-colors ${securityPrefs[item.key as keyof typeof securityPrefs] ? 'bg-emerald-400' : 'bg-white/20'}`}
                >
                  <span className={`block w-5 h-5 bg-white rounded-full transition-transform ${securityPrefs[item.key as keyof typeof securityPrefs] ? 'translate-x-5' : 'translate-x-0.5'}`}></span>
                </button>
              </div>
            ))}
          </div>
        )}

        {step === 4 && (
          <p className="text-white/65 text-sm mt-3">Your profile is configured. You can now open Canvas and execute securely.</p>
        )}

        <div className="mt-6 flex justify-between">
          <button
            onClick={() => setStep((s) => Math.max(0, s - 1))}
            disabled={step === 0}
            className="px-4 py-2 rounded-xl border border-white/15 text-white/80 disabled:opacity-30"
          >
            Back
          </button>

          {step < 4 ? (
            <button
              onClick={() => setStep((s) => Math.min(4, s + 1))}
              className="px-5 py-2 rounded-xl bg-white text-black text-sm font-medium hover:bg-white/90"
            >
              Continue
            </button>
          ) : (
            <button
              onClick={finish}
              className="px-5 py-2 rounded-xl bg-white text-black text-sm font-medium hover:bg-white/90"
            >
              Open Canvas
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
